'use client';

import type {ReactNode} from 'react';
import {AppShell} from '@astryxdesign/core/AppShell';
import {Theme} from '@astryxdesign/core/theme';
import {themes, defaultThemeSlug} from '../astryx-themes';
import {AppNav} from './AppNav';

/**
 * Client-side root: theme (generated by `astryx theme add/use`) and the app shell,
 * which paints the page background and holds the side navigation.
 */
export function Providers({children}: {children: ReactNode}) {
  return (
    <Theme theme={themes[defaultThemeSlug]} mode="system">
      <AppShell variant="wash" sideNav={<AppNav />}>
        {children}
      </AppShell>
    </Theme>
  );
}
